        await OnSortChanged.InvokeAsync(value);
    }
}
"}

{"path": "/tmp/sv-492f655944564b85b073a6ee353f6746/Components/Pages/Catalog/CatalogPagination.razor", "file_text": "@namespace sv_492f655944564b85b073a6ee353f6746.Components.Pages.Catalog

<nav class="catalog-pagination">
    <button class="btn-page" disabled="@(Page <= 1)" @onclick="() => GoToPage(Page - 1)">
        Previous
    </button>

    @for (int i = 1; i <= TotalPages; i++)
    {
        var pageNum = i;
        <button class="btn-page @(pageNum == Page ? "active" : "")"
                @onclick="() => GoToPage(pageNum)">
            @pageNum
        </button>
    }

    <button class="btn-page" disabled="@(Page >= TotalPages)" @onclick="() => GoToPage(Page + 1)">
        Next
    </button>
</nav>

@code {
    [Parameter]
    public int Page { get; set; }

    [Parameter]
    public int TotalCount { get; set; }

    [Parameter]
    public int PageSize { get; set; }

    [Parameter]
    public EventCallback<int> OnPageChanged { get; set; }

    private int TotalPages => PageSize > 0 ? (int)Math.Ceiling((double)TotalCount / PageSize) : 1;

    private async Task GoToPage(int page)
    {
        if (page >= 1 && page <= TotalPages)
        {
            await OnPageChanged.InvokeAsync(page);
        }
    }
}
"}

